import { Player } from '../player.js';
import { Spec } from '../proto/common.js';
import { EventID } from '../typed_event.js';
import { BooleanPicker } from './boolean_picker.js';
import { Component } from './component.js';
import { EnumPicker } from './enum_picker.js';
import { NumberPicker } from './number_picker.js';

// Proc meta gems the sim can weave in (must match isWeaveableProcMeta in sim/core/meta_gem_weave.go).
const WEAVE_GEMS: Array<{ name: string, value: number }> = [
	{ name: 'Thundering Skyflare Diamond', value: 41400 },
	{ name: 'Thundering Skyfire Diamond', value: 32410 },
	{ name: 'Mystical Skyfire Diamond', value: 25893 },
	{ name: 'Insightful Earthsiege Diamond', value: 41401 },
	{ name: 'Insightful Earthstorm Diamond', value: 25901 },
];

// Settings widget for meta gem weaving: the helm's meta gem is the main meta, and the chosen proc
// meta is socketed over it whenever its ICD is ready, then swapped back as soon as it procs.
export class MetaGemWeavePicker<SpecType extends Spec> extends Component {
	constructor(parentElem: HTMLElement, player: Player<SpecType>) {
		super(parentElem, 'meta-gem-weave-picker-root');

		new BooleanPicker(this.rootElem, player, {
			reverse: true,
			label: 'Enable Meta Gem Weaving',
			labelTooltip: `
				<p>By default, weaves through the entire fight and in prepull.</p>
				<p>To weave only under conditions use the <b>Meta Gem Swap</b> APL action: once the APL uses it, the swapped meta is only socketed by the APL and not automatically.</p>
			`,
			extraCssClasses: ['input-inline'],
			getValue: (player: Player<SpecType>) => player.getMetaGemWeave().enabled,
			setValue: (eventID: EventID, player: Player<SpecType>, newValue: boolean) => {
				const weave = player.getMetaGemWeave();
				weave.enabled = newValue;
				if (newValue && !weave.gemId) {
					weave.gemId = WEAVE_GEMS[0].value;
				}
				player.setMetaGemWeave(eventID, weave);
			},
			changedEvent: (player: Player<SpecType>) => player.metaGemWeaveChangeEmitter,
		});

		const optionsContainer = document.createElement('div');
		this.rootElem.appendChild(optionsContainer);

		new EnumPicker(optionsContainer, player, {
			label: 'Swapped Meta',
			labelTooltip: 'The proc meta gem that is woven in over the helm\'s meta gem.',
			values: WEAVE_GEMS,
			getValue: (player: Player<SpecType>) => player.getMetaGemWeave().gemId || WEAVE_GEMS[0].value,
			setValue: (eventID: EventID, player: Player<SpecType>, newValue: number) => {
				const weave = player.getMetaGemWeave();
				weave.gemId = newValue;
				player.setMetaGemWeave(eventID, weave);
			},
			changedEvent: (player: Player<SpecType>) => player.metaGemWeaveChangeEmitter,
		});

		new NumberPicker(optionsContainer, player, {
			label: 'Weaving Reaction Time (ms)',
			labelTooltip: 'Delay before each re-socket (ICD ready -> Swapped Meta in, proc -> helm meta back). Leave at 0 for addon-automated weaving; add your reaction time when weaving manually.',
			getValue: (player: Player<SpecType>) => player.getMetaGemWeave().reactionTimeMs,
			setValue: (eventID: EventID, player: Player<SpecType>, newValue: number) => {
				const weave = player.getMetaGemWeave();
				weave.reactionTimeMs = Math.max(0, Math.min(5000, newValue));
				player.setMetaGemWeave(eventID, weave);
			},
			changedEvent: (player: Player<SpecType>) => player.metaGemWeaveChangeEmitter,
		});

		const toggleEnabled = () => {
			optionsContainer.classList.toggle('hide', !player.getMetaGemWeave().enabled);
		};
		player.metaGemWeaveChangeEmitter.on(toggleEnabled);
		toggleEnabled();
	}
}
