import { element } from 'tsx-vanilla';

import { setItemQualityCssClass } from '../../css_utils';
import { IndividualSimUI } from '../../individual_sim_ui';
import { Player } from '../../player';
import { GemColor, Profession } from '../../proto/common';
import { UIGem as Gem } from '../../proto/ui.js';
import { ActionId } from '../../proto_utils/action_id';
import { TypedEvent } from '../../typed_event';
import { Component } from '../component';
import { ContentBlock } from '../content_block';
import { GemSelectorModal } from './bulk_tab';

interface GemSummaryData {
	gem: Gem;
	count: number;
}

export class GemSummary extends Component {
	private readonly simUI: IndividualSimUI<any>;
	private readonly player: Player<any>;

	private readonly container: ContentBlock;

	constructor(parent: HTMLElement, simUI: IndividualSimUI<any>, player: Player<any>) {
		super(parent, 'gem-summary-root');
		this.simUI = simUI;
		this.player = player;

		this.container = new ContentBlock(this.rootElem, 'gem-summary-container', {
			header: { title: 'Gem Summary' },
		});
		player.gearChangeEmitter.on(() => this.updateTable());

		const headerElement = this.container.headerElement;
		if (headerElement) {
			const actions = (
				<div className="gem-summary-actions">
					<button
						className="btn btn-sm btn-link gem-equip-all-button"
						onclick={() => {
							this.openEquipAllGemsSelector();
						}}>
						<i className="fas fa-gem me-1"></i>
						Equip All Gems
					</button>
					<button
						className="btn btn-sm btn-link gem-reset-button"
						onclick={() => {
							this.unequipAllGems();
						}}>
						<i className="fas fa-times me-1"></i>
						Unequip All Gems
					</button>
				</div>
			);
			headerElement.appendChild(actions);
		}
	}

	private unequipAllGems() {
		this.player.setGear(TypedEvent.nextEventID(), this.player.getGear().withoutGems());
	}

	private openEquipAllGemsSelector() {
		// The modal removes itself from the DOM when closed, so build a fresh one each time.
		const selector = new GemSelectorModal(
			this.simUI.rootElem,
			this.simUI,
			GemColor.GemColorPrismatic,
			itemData => {
				this.equipGemInAllSockets(itemData.item);
				selector.close();
			},
			{
				title: 'Equip Gem In All Sockets',
				// Unique and JC-only gems can't fill every socket, so they're left out.
				gemFilter: gem => !gem.unique && gem.requiredProfession == Profession.ProfessionUnknown,
				hideSocketControls: true,
			},
		);
		selector.show();
	}

	// Puts the gem in every non-meta socket, including Blacksmithing sockets. The meta gem is kept.
	private equipGemInAllSockets(gem: Gem) {
		const isBlacksmithing = this.player.isBlacksmithing();
		let gear = this.player.getGear();

		for (const slot of gear.getItemSlots()) {
			let item = gear.getEquippedItem(slot);
			if (!item) {
				continue;
			}

			item.curSocketColors(isBlacksmithing).forEach((socketColor, socketIdx) => {
				if (socketColor != GemColor.GemColorMeta) {
					item = item!.withGem(gem, socketIdx);
				}
			});
			gear = gear.withEquippedItem(slot, item, true);
		}

		this.player.setGear(TypedEvent.nextEventID(), gear);
	}

	private updateTable() {
		this.container.bodyElement.innerHTML = ``;
		const fullGemList = this.player.getGear().getAllGems(this.player.isBlacksmithing());
		const gemCounts: Record<string, GemSummaryData> = {};

		for (const gem of fullGemList) {
			if (gemCounts[gem.name]) {
				gemCounts[gem.name].count += 1;
			} else {
				gemCounts[gem.name] = {
					gem: gem,
					count: 1,
				};
			}
		}

		for (const gemName of Object.keys(gemCounts)) {
			const gemData = gemCounts[gemName];
			const row = document.createElement('div');
			row.classList.add('d-flex', 'align-items-center', 'justify-content-between');
			row.innerHTML = `
				<a class="gem-summary-link" data-whtticon="false" target="_blank">
					<img class="gem-icon"/>
					<div>${gemName}</div>
				</a>
				<div>${gemData.count.toFixed(0)}</div>
			`;

			const gemLinkElem = row.querySelector('.gem-summary-link') as HTMLAnchorElement;
			const gemIconElem = row.querySelector('.gem-icon') as HTMLImageElement;

			setItemQualityCssClass(gemLinkElem, gemData.gem.quality);

			ActionId.fromItemId(gemData.gem.id)
				.fill()
				.then(filledId => {
					gemIconElem.src = filledId.iconUrl;
					filledId.setWowheadHref(gemLinkElem);
				});

			this.container.bodyElement.appendChild(row);
		}
	}
}
